'use strict';

const { withQuery } = require('../utils');

/**
 * /v1/contactless — reusable "tap to pay" / QR tokens (e.g. for in-person
 * point-of-sale collection).
 */
class Contactless {
  constructor(client) {
    this.client = client;
  }

  /**
   * List contactless tokens.
   * @param {object} [params]
   */
  list(params) {
    return this.client.request('GET', withQuery('/v1/contactless', params));
  }

  /**
   * Create a contactless token.
   * @param {object} params
   * @param {number} [params.amount]        Omit for a variable-amount token
   * @param {string} [params.currency]
   * @param {string} params.label
   * @param {string} [params.description]
   * @param {string} [params.external_ref]
   * @param {boolean} [params.single_use]
   * @param {number} [params.max_uses]
   * @param {string} [params.expires_at]
   * @param {string} [params.url_success]
   * @param {string} [params.url_error]
   * @param {object} [params.metadata]
   */
  create(params) {
    return this.client.request('POST', '/v1/contactless', params);
  }

  /**
   * Get public info about a contactless token (label, amount if fixed, status).
   * @param {string} token
   */
  info(token) {
    return this.client.request('GET', `/v1/contactless/${encodeURIComponent(token)}/info`);
  }

  /**
   * Pay a contactless token via Mobile Money.
   * @param {string} token
   * @param {object} params  operator_code, external_ref, otp?, amount? (if variable), payer_*...
   */
  pay(token, params) {
    return this.client.request('POST', `/v1/contactless/${encodeURIComponent(token)}/pay`, params);
  }

  /**
   * Delete/deactivate a contactless token.
   * @param {string} token
   */
  delete(token) {
    return this.client.request('DELETE', `/v1/contactless/${encodeURIComponent(token)}`);
  }
}

module.exports = Contactless;
